 async Task Reports(PortalModel m,List<JsonNode> clubs,string? clubId)
 {
  m.Title="Relatórios da unidade";m.Description="Indicadores de uso e financeiro para acompanhar a gestão.";clubId??=clubs.FirstOrDefault()?["id"]?.ToString();
  m.Sections.Add(new("Unidade consultada",Forms:[Form("relatorio-filtrar","Consultar relatório",[Select("clubeId","Unidade",Options(clubs),clubId)])]));if(clubId is null)return;
  var summary=await api.Get("api/relatorios/resumo?clubeId="+clubId);m.Stats.AddRange([new("Reservas",Text(summary,"reservas"),"Reservas confirmadas"),new("Turmas",Text(summary,"turmas"),"Turmas da unidade"),new("Inscrições",Text(summary,"inscricoes"),"Participações confirmadas"),new("Acessos",Text(summary,"acessos"),"Entradas autorizadas")]);
  if(Has("AdministradorGeral","Presidente","Tesoureiro")){var f=await api.Get("api/relatorios/financeiro?clubeId="+clubId);m.Sections.Add(new("Resumo financeiro","Valores exclusivamente simulados.",Table:new(["Quitadas","Em aberto","Vencidas","Total pago","Total aberto"],[new([C(Text(f,"pagas")),C(Text(f,"emAberto")),C(Text(f,"vencidas")),C(Money(f,"totalPago")),C(Money(f,"totalAberto"))])])));}
 }
 async Task Audit(PortalModel m){m.Title="Auditoria";m.Description="Rastreabilidade das alterações críticas do sistema.";var logs=await List("api/auditoria");m.Sections.Add(new("Eventos registrados",Table:new(["Data e hora","Operação","Entidade","Registro","Usuário"],logs.OrderByDescending(x=>Val(x,"dataHora")).Take(250).Select(a=>new Row([C(When(a,"dataHora")),C(Text(a,"acao")),C(Text(a,"entidade")),C(Text(a,"entidadeId")),C(Text(a,"usuarioId"))])).ToList())));}
}
